package com.aicharacter.v3;
/** Range gate shared by planned object actions. */
public final class PhysicalInteraction{private PhysicalInteraction(){}public static float range(WorldObject o){return o==null?0:(o.interactionRadius>0?o.interactionRadius:Math.max(28,Math.min(72,o.width*.35f+20)));}public static boolean inRange(WorldState s,WorldObject o){if(o==null)return false;WorldArea a=s.world.areaAt(s.haruX);return a!=null&&a.id.equals(o.areaId)&&Math.abs(s.haruX-(o.interactionX==0?o.x:o.interactionX))<=range(o);}public static String trace(WorldState s,WorldObject o){if(o==null)return"target=<null> execute=false";float tx=o.interactionX==0?o.x:o.interactionX,d=Math.abs(s.haruX-tx),r=range(o);return"target="+o.id+" targetX="+(int)tx+" currentX="+(int)s.haruX+" distance="+(int)d+" range="+(int)r+" execute="+(d<=r);}}
